<script setup lang="ts">import { ref } from "vue"; import { useRouter } from "vue-router"; import { createItem } from "../api"; const router = useRouter(); const form = ref({ sku: "", name: "", description: "", unit: "ud", minimumStock: 0, salePriceCents: 0, taxRate: 21 }); const error = ref(""); async function save() { try { const item = await createItem(form.value); void router.push({ name: "inventory.detail.general", params: { id: item.id } }); } catch (reason) { error.value = (reason as Error).message; } }</script><template><form class="entity-form" @submit.prevent="save"><header><div><p class="eyebrow">Almacen</p><h1>Nuevo material</h1></div></header><fieldset><legend>Catalogo</legend><label>SKU<input v-model="form.sku" required /></label><label>Nombre<input v-model="form.name" required /></label><label>Descripcion<textarea v-model="form.description" rows="3" /></label><label>Unidad<input v-model="form.unit" /></label><label>Stock minimo<input v-model.number="form.minimumStock" type="number" min="0" /></label><label>Precio de venta (centimos)<input v-model.number="form.salePriceCents" type="number" min="0" /></label><label>IVA (%)<input v-model.number="form.taxRate" type="number" min="0" max="100" step="0.01" /></label></fieldset><p v-if="error" class="feedback error">{{ error }}</p><footer><button class="secondary" type="button" @click="router.back()">Cancelar</button><button>Guardar material</button></footer></form></template>